import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, SpotLight, AmbientLight } = ctx.THREE;
  const group = new Group();
  const timelines = [];
  const cleanups = [];

  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = textContent.find(item => item.role === 'kicker') || { text: 'AS FEATURED IN' };
  const brandItems = textContent.filter(item => item.role === 'brand-mark');

  const fallbackBrands = ['HODINKEE', 'MONOCLE', 'WALLPAPER', 'ESQUIRE', 'WIRED', 'FINANCIAL TIMES'];
  const finalBrands = brandItems.length >= 6 ? brandItems.map(i => i.text) : fallbackBrands;

  const bgPlaneGeo = new PlaneGeometry(12, 10);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
  });

  const stop0 = color('#1a1a22');
  const stop1 = color('#121218');
  bgMat.colorNode = mix(stop1, stop0, uv().y);

  const bgMesh = new Mesh(bgPlaneGeo, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  const kickerText = ctx.fontAtlas.createText(kickerItem.text, {
    fontSize: 10,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 3
  });
  kickerText.position.set(0, 1.4, 0.05);
  group.add(kickerText);

  const ambient = new AmbientLight('#16161d', 0.6);
  group.add(ambient);

  const rakeLight = new SpotLight('#e8ecf2', 1.4, 15, Math.PI / 4, 0.5, 1.0);
  rakeLight.position.set(-4, 3, 4);
  rakeLight.target.position.set(0, 0, 0);
  group.add(rakeLight);
  group.add(rakeLight.target);

  const accentLight = new SpotLight('#ff2a38', 0.8, 10, Math.PI / 5, 0.3, 1.0);
  accentLight.position.set(4, -3, 3);
  accentLight.target.position.set(0, 0, 0);
  group.add(accentLight);
  group.add(accentLight.target);

  const tileWidth = 1.0;
  const tileHeight = 0.62;
  const chamfer = 0.02;
  const gap = 0.25;

  const cols = 3;
  const rows = 2;
  const totalWidth = cols * tileWidth + (cols - 1) * gap;
  const totalHeight = rows * tileHeight + (rows - 1) * gap;
  const startX = -totalWidth / 2 + tileWidth / 2;
  const startY = totalHeight / 2 - tileHeight / 2;

  const tileGeometry = new BoxGeometry(tileWidth, tileHeight, 0.08);

  const tiles = [];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const index = r * cols + c;
      const brandText = finalBrands[index % finalBrands.length];

      const tileGroup = new Group();
      const posX = startX + c * (tileWidth + gap);
      const posY = startY - r * (tileHeight + gap);
      tileGroup.position.set(posX, posY - 0.2, 0); 

      const tileMat = new MeshStandardNodeMaterial({
        roughness: 0.55,
        metalness: 0.5,
        clearcoat: 0.2,
        clearcoatRoughness: 0.3,
      });
      tileMat.colorNode = mix(color('#121218'), color('#1a1a22'), uv().y);

      const tileMesh = new Mesh(tileGeometry, tileMat);
      tileGroup.add(tileMesh);

      const label = ctx.fontAtlas.createText(brandText, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 1
      });
      label.position.set(0, 0, 0.045);

      const labelMat = label.material || label.children?.[0]?.material;
      if (labelMat) {
        labelMat.transparent = true;
        labelMat.opacity = 0.78;
      }

      tileGroup.add(label);
      group.add(tileGroup);
      tiles.push({ tileGroup, label, labelMat, index });

      const hitPlaneGeo = new PlaneGeometry(tileWidth, tileHeight);
      const hitPlaneMat = new MeshStandardNodeMaterial({ visible: false });
      const hitPlane = new Mesh(hitPlaneGeo, hitPlaneMat);
      hitPlane.position.z = 0.05;
      tileGroup.add(hitPlane);

      let tileTimeline = null;
      hitPlane.userData.handlers = {
        pointerover: () => {
          if (tileTimeline) tileTimeline.kill();
          tileTimeline = gsap.timeline();
          tileTimeline.to(tileGroup.position, { z: 0.08, duration: 0.16, ease: 'power1.out' });
          if (labelMat) {
            tileTimeline.to(labelMat, { opacity: 1.0, duration: 0.16, ease: 'power1.out' }, 0);
          }
        },
        pointerout: () => {
          if (tileTimeline) tileTimeline.kill();
          tileTimeline = gsap.timeline();
          tileTimeline.to(tileGroup.position, { z: 0.0, duration: 0.2, ease: 'power2.out' });
          if (labelMat) {
            tileTimeline.to(labelMat, { opacity: 0.78, duration: 0.2, ease: 'power2.out' }, 0);
          }
        }
      };
    }
  }

  tiles.forEach(({ tileGroup, index }) => {
    const r = Math.floor(index / cols);
    const c = index % cols;
    const delay = (r * cols + c) * 0.08;
    const targetY = tileGroup.position.y + 0.2;

    gsap.fromTo(tileGroup.position, 
      { y: tileGroup.position.y, z: -0.1 },
      { y: targetY, z: 0, duration: 0.5, delay, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
    );

    gsap.fromTo(tileGroup.scale,
      { x: 0.8, y: 0.8, z: 0.8 },
      { x: 1, y: 1, z: 1, duration: 0.5, delay, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
    );
  });

  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const result = ctx.primitives[primitive.name](group, primitive.params);
        if (result && result.cleanup) {
          cleanups.push(result.cleanup);
        }
      }
    });
  }

  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    cleanups.forEach(fn => fn());
    bgPlaneGeo.dispose();
    bgMat.dispose();
    tileGeometry.dispose();
    tiles.forEach(t => {
      if (t.labelMat) t.labelMat.dispose();
    });
  };

  return group;
}_
